"""Write the internal SOTA failure report required by the repaired protocol."""

from __future__ import annotations

from artifact_utils import ROOT, RUN_DIR, append_manifest_run, read_json


OUT = ROOT / "INTERNAL_SOTA_FAILURE_REPORT.md"


def main() -> None:
    tables = read_json(RUN_DIR / "tables.json")
    lines = [
        "# Internal SOTA Failure Report",
        "",
        "This report is generated by `_bestrec_run/build_internal_report.py` because the repaired",
        "BEST-Rec audit standard does not currently permit a SOTA claim.",
        "",
        "## Decision",
        "",
        "**Do not submit as a SOTA paper yet.** The current artifact set may be used as an",
        "internal negative-result / algorithm-development report only.",
        "",
        "## Blocking Limitations",
        "",
    ]
    for item in tables.get("limitations", []):
        lines.append(f"- {item}")
    lines += [
        "",
        "## Mandatory Baseline Audit",
        "",
        "| Baseline | Status | Seeds | Notes |",
        "|---|---:|---:|---|",
    ]
    for name, entry in tables.get("sota_audit", {}).get("mandatory_baselines", {}).items():
        seeds = ",".join(str(s) for s in entry.get("seeds", [])) or "-"
        notes = str(entry.get("notes", "")).replace("\n", " ")
        lines.append(f"| `{name}` | {entry.get('status', '-')} | {seeds} | {notes} |")
    win = tables.get("sota_audit", {}).get("win_condition", {})
    lines += [
        "",
        "## LC2C++ Win Condition",
        "",
        f"- Status: `{win.get('status', 'not_evaluated')}`",
        f"- Notes: {win.get('notes', 'No win-condition audit has been generated.')}",
        "",
        "## Required Repair Before SOTA Submission",
        "",
        "- Generate full-catalog cold-item rankings where cold items compete with all warm and cold candidates.",
        "- Run faithful WMF-backed DropoutNet, CLCRec/MELT-style cold-start, BLaIR-style text retrieval, tuned LightGCN, tuned MultiVAE, and sparse iALS with configs, runtimes, seeds, and per-user records.",
        "- Run the predeclared LC2C++ variants and keep the claim only if macro-average NDCG@10 beats the best modern baseline and wins on at least 3 of 4 datasets.",
        "- Require Holm-corrected per-user Wilcoxon and user/item/fold clustered bootstrap confidence intervals above zero.",
        "- Rebuild `results_FINAL.json`, `significance.json`, `tables.json`, figures, manifest, and PDF from the canonical `run_all.py` path.",
        "",
    ]
    OUT.write_text("\n".join(lines), encoding="utf-8")
    append_manifest_run(
        command=["python", "build_internal_report.py"],
        inputs=[RUN_DIR / "tables.json"],
        outputs=[OUT],
        note="Generated internal failure report because SOTA gate did not pass.",
    )
    print(f"Wrote {OUT}")


if __name__ == "__main__":
    main()
